using eShop.Catalog.Core.Configuration;
using eShop.Catalog.Infrastructure.Data;
using eShop.Catalog.Infrastructure.Services;
using eShopNet8.Mvc.Api;
using eShopNet8.Mvc.Extensions;
using eShopNet8.Mvc.Health;

var builder = WebApplication.CreateBuilder(args);

builder.Logging.AddCatalogLogging(builder.Configuration);        // T2
builder.Services.AddCatalogSettings(builder.Configuration);      // scaffold (UseMockData, UseCustomizationData)
builder.Services.AddCatalogData(builder.Configuration);          // T1
builder.Services.AddCatalogServices(builder.Configuration);      // T2
builder.Services.AddCatalogMvc(builder.Configuration);           // T3
builder.Services.AddCatalogApi(builder.Configuration);           // T4
builder.Services.AddCatalogHealth(builder.Configuration);        // T6

var app = builder.Build();

app.UseCatalogMvc();                                             // T3 (error handling, static files, session, routing)
app.MapCatalogHealth();                                          // T6
app.MapCatalogApi();                                             // T4
app.MapCatalogMvc();                                             // T3

await app.Services.InitializeCatalogDataAsync();                 // T1
app.Run();

